import asyncio
from collections.abc import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    """Run ``tasks`` with at most ``max_concurrent`` running at once.

    If run_tasks is cancelled (e.g. asyncio.run() handling Ctrl+C), every
    in-flight task is cancelled and awaited so its cleanup code (finally
    blocks, ``async with`` exits, ``except CancelledError`` handlers) runs
    before run_tasks returns. Tasks that never started are not started.

    If a task raises, the remaining tasks are cancelled (and allowed to clean
    up) and the first exception is re-raised.
    """
    if max_concurrent < 1:
        raise ValueError("max_concurrent must be >= 1")
    if not tasks:
        return

    pending = iter(tasks)
    stop = False

    async def worker() -> None:
        nonlocal stop
        while not stop:
            try:
                job = next(pending)
            except StopIteration:
                return
            await job()

    workers = [
        asyncio.create_task(worker())
        for _ in range(min(max_concurrent, len(tasks)))
    ]

    try:
        # Return as soon as all workers finish or one fails.
        done, _ = await asyncio.wait(workers, return_when=asyncio.FIRST_EXCEPTION)
        for w in done:
            if not w.cancelled() and w.exception() is not None:
                raise w.exception()
    finally:
        stop = True
        for w in workers:
            if not w.done():
                w.cancel()
        # Wait for every worker to finish its cleanup, even if we get
        # cancelled again (e.g. repeated Ctrl+C) while waiting.
        remaining = [w for w in workers if not w.done()]
        cancelled_again = False
        while remaining:
            try:
                await asyncio.wait(remaining)
            except asyncio.CancelledError:
                cancelled_again = True
            remaining = [w for w in remaining if not w.done()]
        # Retrieve exceptions so asyncio doesn't log "never retrieved".
        for w in workers:
            if not w.cancelled():
                w.exception()
        if cancelled_again:
            raise asyncio.CancelledError

